/* @autogenerated */
import { DOCUMENT } from '@angular/common';
import {
  DestroyRef,
  computed,
  effect,
  EnvironmentProviders,
  inject,
  Injectable,
  provideAppInitializer,
  signal,
} from '@angular/core';
import { APP_CONFIG } from '../config/app-config.service';
import { persistedSignal } from '../state/app-state.service';

/** `auto` sigue al sistema operativo; `light` y `dark` lo fuerzan. */
export type ThemeMode = 'auto' | 'light' | 'dark';

export const THEME_MODES: readonly ThemeMode[] = ['auto', 'light', 'dark'];

/** Clase que se pone en `<html>` por cada modo forzado (ver `src/styles/_material-theme.scss`). */
const THEME_CLASSES: Record<Exclude<ThemeMode, 'auto'>, string> = {
  light: 'theme-light',
  dark: 'theme-dark',
};

@Injectable({
  providedIn: 'root',
})
export class ThemeModeService {
  private readonly root = inject(DOCUMENT).documentElement;
  private readonly config = inject(APP_CONFIG);
  private readonly systemDark = signal(false);

  /** Modo elegido por el usuario o, si no ha elegido, `theme.mode` de la configuración. Se guarda en `localStorage`. */
  public readonly mode = persistedSignal<ThemeMode>(
    'theme-mode',
    computed(() => reviveMode(this.config().theme.mode)),
    undefined,
    reviveMode,
  );

  /** `true` si se está pintando en oscuro: forzado o porque el sistema lo pide en modo `auto`. */
  public readonly dark = computed(() => {
    const mode = this.mode();
    return mode === 'auto' ? this.systemDark() : mode === 'dark';
  });

  constructor() {
    effect(() => this.apply(this.mode()));
    this.watchSystem();
  }

  private watchSystem(): void {
    const query = typeof matchMedia === 'function' ? matchMedia('(prefers-color-scheme: dark)') : null;
    if (!query) {
      return;
    }
    this.systemDark.set(query.matches);
    const listener = (event: MediaQueryListEvent) => this.systemDark.set(event.matches);
    query.addEventListener('change', listener);
    inject(DestroyRef).onDestroy(() => query.removeEventListener('change', listener));
  }

  private apply(mode: ThemeMode): void {
    Object.entries(THEME_CLASSES).forEach(([key, css]) => this.root.classList.toggle(css, key === mode));
  }
}

/** Aplica el modo guardado al arrancar, antes de pintar el shell. */
export function provideThemeMode(): EnvironmentProviders {
  return provideAppInitializer(() => {
    inject(ThemeModeService);
  });
}

function reviveMode(raw: unknown): ThemeMode {
  return THEME_MODES.includes(raw as ThemeMode) ? (raw as ThemeMode) : 'auto';
}
